\section{IPM derivations} \label{sec:ipm_derivations}
Define the function class $G_{3L}$ of ReLU neural networks of the form $g(x) = \pm \sigma (\sum_{j=1}^{m_1} w_j \sigma(\langle \theta_j, x \rangle - b_j) + w_0 )$ such that $\sum_{j=1}^{m_1} |w_j| \cdot \|(\theta_j,b_j)\|_2 + |w_0| \leq 1$. 
\begin{lemma} \label{lem:G_3l}
Any function in $F_{3L}$ may be written as a convex combination of functions in $G_{3L}$ and the constant function 1. 
\end{lemma}
\begin{proof}
Let 
\begin{align}
f_{\mathcal{W}}(x) = \sum_{i=1}^{m_2} w_i \sigma \left(\sum_{j=1}^{m_1} W_{i,j} \sigma\left(\langle \theta_j, x \rangle - b_j \right) + W_{i,0} \right) + w_0. 
\end{align}
belong to $F_{3L}$, which means that $\text{PN}_b(\mathcal{W}) = \sum_{i=1}^{m_2} |w_i| ( \sum_{j=1}^{m_1} |W_{i,j}| \cdot \|(\theta_j,b_j)\|_2 + |W_{i,0}|) + |w_0| \leq 1$.
We may renormalize the weights such that $\sum_{j=1}^{m_1} |W_{i,j}| \cdot \|(\theta_j,b_j)\|_2 + |W_{i,0}| = 1$ for all $i$, by moving the appropriate factors outside of the ReLU activation thanks to the 1-homogeneity. Then, $\text{PN}_b(\mathcal{W}) = \sum_{i=0}^{m_2} |w_i| \leq 1$. We may further renormalize the weights such that $\sum_{i=0}^{m_2} |w_i| = 1$ and $\sum_{j=1}^{m_1} |W_{i,j}| \cdot \|(\theta_j,b_j)\|_2 + |W_{i,0}| \leq 1$ for all $i$.

Setting $g_i(x) = \text{sign}(w_i) \sigma \left(\sum_{j=1}^{m_1} W_{i,j} \sigma\left(\langle \theta_j, x \rangle - b_j \right) + W_{i,0} \right)$, we obtain the expression $f_{\mathcal{W}}(x) = \sum_{i=1}^{m_2} |w_i| g_i(x) + |w_0|$. That is, $f_{\mathcal{W}}$ can be written as a convex combination of $\{g_i\}_{i=1}^{m_2}$ and the constant function 1. Note that $g_i$ belongs to $G_{3L}$, which concludes the proof. 
\end{proof}

Since $f \mapsto \pm(\mathbb{E}_{x \sim \mu}[f(x)] - \mathbb{E}_{x \sim \nu}[f(x)])$ are concave mappings, their suprema over $G_{3L}$ is equal to their suprema over the convex hull $\text{conv}(G_{3L})$. Since $\mathbb{E}_{x \sim \mu}[f(x)] - \mathbb{E}_{x \sim \nu}[f(x)]$ is 0 when $f$ is a constant function, by \autoref{lem:G_3l} the suprema over $\text{conv}(G_{3L})$ are equal to the suprema over $F_{3L}$, which concludes the proof of equation \eqref{eq:3L_ipm}. Equation \eqref{eq:2L_ipm} follows from a similar argument. Equation \eqref{eq:H_ipm} is derived using the proof of Lemma 2 of \cite{domingoenrich2021separation}. 

\vspace{-10pt}
\section{Proofs of \autoref{sec:separation_3_v_2}} \label{sec:proofs_3_v_2}
\noindent\textbf{Proof of \autoref{lem:rho_d_conv}.}
If we take a Schwartz function $\phi \in \mathcal{S}(\mathbb{R}^d)$, we have
\begin{align}
\begin{split}
    &\langle \pi_d*g_d, \phi \rangle = \langle g_d(y), \langle \phi(x + y), \pi_d(x) \rangle \rangle \\ &= \int_{\mathbb{R}^d} \frac{1}{(2\pi \sigma^2)^{d/2}} e^{-\frac{\|y\|^2}{2\sigma^2}} \left\langle \phi(x+y), \frac{2}{4^d} \sum_{\beta \in \mathcal{B}^d} \prod_{i=1}^{d} \chi_{\beta_i} \delta_{\beta} \right\rangle \, dy \\ &= \frac{2}{(4\sqrt{2\pi \sigma^2})^d} \int_{\mathbb{R}^d} e^{-\frac{\|y\|^2}{2\sigma^2}} \sum_{\beta \in \mathcal{B}^d} \prod_{i=1}^{d} \chi_{\beta_i} \phi(y+\beta) \, dy \\ &= \frac{2}{(4\sqrt{2\pi \sigma^2})^d} \sum_{\beta \in \mathcal{B}^d} \prod_{i=1}^{d} \chi_{b_i} \int_{\mathbb{R}^d} e^{-\frac{\|y\|^2}{2\sigma^2}} \phi(y+\beta) \, dy 
    \\ &= \frac{2}{(4\sqrt{2\pi \sigma^2})^d} \sum_{\beta \in \mathcal{B}^d} \prod_{i=1}^{d} \chi_{b_i} \int_{\mathbb{R}^d} e^{-\frac{\|\tilde{y}-\beta\|^2}{2\sigma^2}} \phi(\tilde{y}) \, d\tilde{y} \\ &=
    \frac{2}{(4\sqrt{2\pi \sigma^2})^d} \int_{\mathbb{R}^d} \sum_{\beta \in \mathcal{B}^d} \prod_{i=1}^{d} \chi_{b_i} e^{-\frac{\|\tilde{y}-\beta\|^2}{2\sigma^2}} \phi(\tilde{y}) \, d\tilde{y} = \langle \rho_d, \phi \rangle.
\end{split}
\end{align}
\qed

\noindent\textbf{Proof of \autoref{prop:inner_prod_fourier}.}
We adapt the argument of Lemma 3 of \cite{domingoenrich2021separation}. Define $\sigma_b : \mathbb{R} \to \mathbb{R}$ as the translation of $\sigma$ by $-b$, i.e. $\sigma_b(x) = \sigma(x-b)$. Note that $\widehat{\sigma_b}(\omega) = e^{-ib\omega} \hat{\sigma}(\omega)$.
We have
\begin{align}
\begin{split}
    &\int_{\mathbb{R}^d} \phi(x) \sigma(\langle \theta, x \rangle - b) \, dx = \int_{\mathbb{R}^d} \phi(x) \sigma_b(\langle \theta, x \rangle) \, dx = \int_{\mathbb{R}^d} \left(\frac{1}{(2\pi)^{d/2}} \int_{\mathbb{R}^d} \hat{\phi}(\omega) e^{i \langle \omega, x \rangle} \, d\omega \right) \sigma_b(\langle \theta, x \rangle) \, dx \\ &= \int_{\text{span}(\theta)} \int_{\text{span}(\theta)^{\perp}} \left(\frac{1}{(2\pi)^{d/2}} \int_{\text{span}(\theta)^{\perp}} \left( \int_{\text{span}(\theta)} \hat{\phi}(\omega) e^{i \langle \omega_\theta, x_{\theta} \rangle} \, d\omega_{\theta} \right) e^{i \langle \omega_{\theta^{\perp}}, x_{\theta^{\perp}} \rangle} \, d\omega_{\theta^{\perp}} \right) \, dx_{\theta^{\perp}} \sigma_b(\langle \theta, x_{\theta} \rangle) \, dx_{\theta} \\ &= \frac{1}{\sqrt{2\pi}} \int_{\text{span}(\theta)} (2\pi)^{(d-1)/2} \int_{\text{span}(\theta)} \hat{\phi}(\omega_{\theta}) e^{i \langle \omega_\theta, x_{\theta} \rangle} \, d\omega_{\theta} \, \sigma_b(\langle \theta, x_{\theta} \rangle) \, dx_{\theta} \\ &= (2\pi)^{(d-1)/2} \int_{\mathbb{R}} \frac{1}{\sqrt{2\pi}} \int_{\mathbb{R}} \hat{\phi}(t\theta) e^{it x} \, dt \, \sigma_b(x) \, dx = (2\pi)^{(d-1)/2} \int_{\mathbb{R}} \frac{1}{\sqrt{2\pi}} \int_{\mathbb{R}} \hat{\phi}(t\theta) e^{it x} \, dt \, \sigma(x-b) \, dx \\ &= (2\pi)^{(d-1)/2} \int_{\mathbb{R}} \frac{1}{\sqrt{2\pi}} \int_{\mathbb{R}} \hat{\phi}(t\theta) e^{it (\tilde{x} + b)} \, dt \, \sigma(\tilde{x}) \, dx = (2\pi)^{(d-1)/2} \langle \check{\sigma}(t), \hat{\phi}(t\theta) e^{itb} \rangle. 
\end{split}
\end{align}
In the third equality, we
rewrite $\mathbb{R}^{d} = \text{span}(\theta) + \text{span}(\theta)^{\perp}$ and we use Fubini's theorem twice. In the fourth equality we
use the following argument: denoting $h(x_{\theta^{\perp}}, \omega_{\theta}) = \int_{\text{span}} \hat{\phi}(\omega_{\theta} + \omega_{\theta}^{\perp}) e^{i \langle \omega_\theta, x_{\theta} \rangle} \, d\omega_{\theta}$, we have that 
\begin{align}
\begin{split}
&\int_{\text{span}(\theta)^{\perp}} \left( \int_{\text{span}(\theta)^{\perp}} h(x_{\theta^{\perp}}, \omega_{\theta}) e^{i \langle \omega_{\theta^{\perp}}, x_{\theta^{\perp}} \rangle} \, d\omega_{\theta^{\perp}} \right) dx_{\theta^{\perp}} = (2\pi)^{(d-1)/2} \int_{\text{span}(\theta)^{\perp}} \hat{h}(-\omega_{\theta^{\perp}}, \omega_{\theta}) \, d\omega_{\theta^{\perp}} \\ &= (2\pi)^{d-1} h(0,\omega_x) = (2\pi)^{d-1} \int_{\text{span}(\theta)} \hat{\phi}(\omega_{\theta}) e^{i \langle \omega_\theta, x_{\theta} \rangle} \, d\omega_{\theta}.
\end{split}
\end{align}
To conclude the proof, note that for any test function $\phi \in \mathcal{S}(\mathbb{R})$, $\langle \check{\sigma}(x), \phi(x) \rangle = \langle \sigma(x), \check{\phi}(x) \rangle = \int_{\mathbb{R}} \sigma(x) \frac{1}{\sqrt{2\pi}} \, \int_{\mathbb{R}} e^{itx} \phi(t) \, dt \, dx = \int_{\mathbb{R}} \sigma(x) \frac{1}{\sqrt{2\pi}} \, \int_{\mathbb{R}} e^{-i(-t)x} \phi(t) \, dt \, dx = \int_{\mathbb{R}} \sigma(x) \frac{1}{\sqrt{2\pi}} \, \int_{\mathbb{R}} e^{-itx} \phi(-t) \, dt \, dx = \langle \hat{\sigma}(x), \phi(-x) \rangle$.
\qed

\vspace{2pt}
\noindent\textbf{Proof of \autoref{lem:pv_upper_bound}.}
Recall that $\text{p.v.} \left[ \frac{1}{\omega} \right] (u) = \int_{0}^{+\infty} \frac{u(\omega) - u(-\omega)}{\omega}$. On the one hand,
\begin{align}
    \left| \int_{0}^{1} \frac{u(x) - u(-x)}{x} \, dx \right| \leq \int_{0}^{1} \frac{|u(x) - u(-x)|}{x} \, dx \leq \int_{0}^{1} \frac{2x}{x} \sup_{y \in (-1,1)} |u'(y)| \, dx = 2 \sup_{y \in (-1,1)} |u'(y)|.
\end{align}
On the other hand,
\begin{align}
\begin{split}
    \left| \int_{1}^{+\infty} \frac{u(x) - u(-x)}{x} \, dx \right| &\leq \int_{1}^{+\infty} \frac{(|u(x)| + |u(-x)|)x^{\delta}}{x^{1+\delta}} \, dx \\ &\leq \int_{1}^{+\infty} 2 \left( \sup_{y \in \mathbb{R} \setminus [-1,1]} |u(y) \cdot y^{\delta}| \right) \frac{1}{x^{1+\delta}} \, dx = \frac{2}{\delta} \left( \sup_{y \in \mathbb{R} \setminus [-1,1]} |u(y) \cdot y^{\delta}| \right).
\end{split}
\end{align}
\qed
\begin{lemma} \label{lem:sup_bound_u_u_prime}
Let $u : \mathbb{R} \to \mathbb{C}$ defined by \eqref{eq:u_def}. Then,
\begin{align}
\begin{split}
    &\sup_{x \in \mathbb{R}} |u'(x)| \leq O\left( \kappa^d \left( d^2 + d |b| + b^2 \right) \right)\\
    &\sup_{x \in \mathbb{R}} |u(x) \cdot x| \leq O\left( \kappa^d \left(\frac{d + |b|}{\sigma} \right) \right)
\end{split}
\end{align}
\end{lemma}
\begin{proof}
Note that
\begin{align}
\begin{split} \label{eq:u_prime}
    u'(t) &= \left(-\sigma^2 t - ib - \sum_{i=1}^d \frac{\theta_i \sin(t \theta_i)}{\cos(t \theta_i)} + 2 \sum_{i=1}^d \frac{\theta_i \cos(2t \theta_i)}{\sin(2t \theta_i)} \right)^2 e^{-\frac{\sigma^2 t^2}{2} - itb} \prod_{i=1}^d \cos(t \theta_i) \sin(2 t \theta_i) \\ &+ \left(-\sigma^2 - \sum_{i=1}^d \frac{\theta_i^2}{\cos^2(t \theta_i)} - 2^2 \sum_{i=1}^d \frac{\theta_i^2}{\sin^2(2t \theta_i)} \right) e^{-\frac{\sigma^2 t^2}{2} - itb} \prod_{i=1}^d \cos(t \theta_i) \sin(2 t \theta_i)
\end{split}
\end{align}
Remark that 
\begin{align}
    \left(- \frac{\theta_i \sin(t \theta_i)}{\cos(t \theta_i)} \right)^2 - \frac{\theta_i^2}{\cos^2(t \theta_i)} = - \theta_i^2, \quad \left( 2 \frac{\theta_i \cos(2t \theta_i)}{\sin(2t \theta_i)} \right)^2 - 2^2 \frac{\theta_i^2}{\sin^2(2t \theta_i)} = - 2^2 \theta_i^2
\end{align}
and that $\sum_{i} \theta_i^2 = \|\theta\|^2 = 1$.
Hence, equation \eqref{eq:u_prime} may be rewritten as $e^{-\frac{\sigma^2 t^2}{2} - itb} \prod_{i=1}^d \cos(t \theta_i) \sin(2 t \theta_i)$ times
\begin{align}
    &
    \sigma^4 t^2 + 2 i b \sigma^2 t - b^2 - 5 + 2(\sigma^2 t + ib)\left( \sum_{i=1}^d \frac{\theta_i \sin(t \theta_i)}{\cos(t \theta_i)} - 2 \sum_{i=1}^d \frac{\theta_i \cos(2t \theta_i)}{\sin(2t \theta_i)} \right)  
    \\ & -4 \sum_{i,j=1}^d \frac{\theta_i \theta_j \sin(t \theta_i) \cos(2t \theta_j)}{\cos(t \theta_i) \sin(2t \theta_j)} + \sum_{\substack{i,j=1 \\ i \neq j}}^{d} \frac{\theta_i \theta_j \sin(t \theta_i) \sin(t \theta_j)}{\cos(t \theta_i) \cos(t \theta_j)} + 4 \sum_{\substack{i,j=1 \\ i \neq j}}^{d} \frac{\theta_i \theta_j \cos(2t \theta_i) \cos(2t \theta_j)}{\sin(2t \theta_i) \sin(2t \theta_j)} 

\end{align}
The functions $t \mapsto |\cos(t \theta_i) \sin(2 t \theta_i)|$ are upper-bounded by 0.77 on $\mathbb{R}$ regardless of the value of $\theta_i$. To see this, define $x = t \theta_i$. Hence, $|\cos(t \theta_i) \sin(2 t \theta_i)| = |\cos(x) \sin(2x)|$. \autoref{lem:bound_cos_sin} shows that $\kappa := \sup_{x \in \mathbb{R}} |\cos(x) \sin(2x)| = 0.7698\dots$. The following upper bounds hold for all $t \in \mathbb{R}$:
\begin{align}
\begin{split}
    \left|
    \prod_{i=1}^d \cos(t \theta_i) \sin(2 t \theta_i) \right| &\leq \kappa^d, \quad \left|t e^{-\frac{\sigma^2 t^2}{2} - itb} 
    \right| \leq \max_{x \in \mathbb{R}} \{ x e^{-\frac{\sigma^2 x^2}{2}} \} = \frac{1}{\sigma \sqrt{e}}, \\
    \left|t^2 e^{-\frac{\sigma^2 t^2}{2} - itb} 
    \right| &\leq 
    \max_{x \geq 0} \{ x e^{-\frac{\sigma^2 x}{2}} \} = \frac{2}{e \sigma^2}.
\end{split}    
\end{align}
Thus, the following is a crude upper bound of $|u'(t)|$ for any $t \in \mathbb{R}$:
\begin{align}
    &\kappa^d \left( \left( \frac{2\sigma^2}{e} + 5 + b^2 + \frac{6d\sigma}{\kappa \sqrt{e}} + \frac{4 d^2}{\kappa^2} + \frac{d(d-1)}{\kappa^2} + \frac{4 d(d-1)}{\kappa^2} \right)^{2} + \left( \frac{2b\sigma}{\sqrt{e}} + \frac{6d |b|}{\kappa} \right)^{2} \right)^{1/2} \\ &= O\left( \kappa^d \left( d^2 + d |b| + b^2 \right) \right)
\end{align}
In the last $O$-notation expression we have only kept the relevant variables: $\sigma$ is relevant because it appears in the numerator and we will take it smaller than 1. 
Similarly, the following is an upper bound on $|t \cdot u(t)|$ for any $t \in \mathbb{R}$:
\begin{align}
    \kappa^d \left( \left( \frac{2}{e} + \frac{2 d a}{\sigma \kappa \sqrt{e}} + \frac{2 d}{\sigma \kappa \sqrt{e}} \right)^2 + \left( \frac{b}{\sigma \sqrt{e}} \right)^2 \right)^{1/2} = O\left( \kappa^d \left(\frac{d + |b|}{\sigma} \right) \right)
\end{align}
\end{proof}
\begin{lemma} \label{lem:bound_cos_sin}
    The function $h(x) = \cos(x) \sin(2x)$ satisfies
    \begin{align}
        \max_{x \in \mathbb{R}} |h(x)| = 0.769800358917917...
    \end{align}
\end{lemma}
\begin{proof}
First note that $h$ has period $2\pi$, which means that we can restrict the search of maximizers to $[-\pi,\pi]$.  
We have that $h'(x) = -\sin(x) \sin(2x) + 2 \cos(x) \cos(2x)$. The condition $h'(x^{*}) = 0$ is necessary for $x^{*}$ to be a local maximizer of $|h|$, and it may be rewritten as $\tan(x) = 2 \, \text{cotan}(2x)$. Remark that $x \to \tan(x)$ is increasing and bijective from $(\pi(z-1/2),\pi(z+1/2))$ to $\mathbb{R}$, and that $x \to 2 \, \text{cotan}(2x)$ is decreasing and bijective from $(\frac{\pi z}{2},\frac{\pi (z+1)}{2})$ to $\mathbb{R}$ for any $z \in \mathbb{Z}$. Thus, there exist $6$ solutions of $h'(x)$ on $[-\pi,\pi]$: one for each interval $(\frac{\pi z}{2},\frac{\pi (z+1)}{2})$ for $z = -2, \dots, 1$, and additional solutions at $\frac{-\pi}{2}$ and at $\frac{\pi}{2})$, where both $\tan(x)$ and $2 \, \text{cotan}(2x)$ take value $+\infty$ and $-\infty$ respectively. With this information, any algorithm that finds local maximizers over intervals allows us to compute the global maximum of $|h|$, which is equal to $0.769800358917917...$, and is attained, among other points, at $0.615478880595691...$
\end{proof}
